def seed_and_convert(apps, schema_editor):
    """Seed the brand list (plus brands already typed on items), then split existing item names
    into brand + model with the same parser the app uses. Names without a known brand are left as they are."""
    Brand = apps.get_model("tracker", "Brand")
    BrandModel = apps.get_model("tracker", "BrandModel")
    JapanItem = apps.get_model("tracker", "JapanItem")

    def add_brand(name):
        name = b.tidy(name)
        key = b.match_key(name)
        if key and not Brand.objects.filter(match_key=key).exists():
            Brand.objects.create(display_name=name, match_key=key)

    for name in b.SEED_BRANDS:
        add_brand(name)
    for name in JapanItem.objects.exclude(brand="").values_list("brand", flat=True).distinct():
        add_brand(name)

    known = [(x.match_key, x.display_name) for x in Brand.objects.all()]
    by_name = {x.display_name: x for x in Brand.objects.all()}

    def models_for(display):
        return [(m.match_key, m.display_name) for m in BrandModel.objects.filter(brand=by_name[display])]

    for item in JapanItem.objects.exclude(item_name=""):
        parsed = b.parse(item.item_name, known, models_for)
        if not parsed.brand:
            continue                                   # no known brand: leave it unchanged
        if parsed.model:
            key = b.match_key(parsed.model)
            if not BrandModel.objects.filter(brand=by_name[parsed.brand], match_key=key).exists():
                BrandModel.objects.create(brand=by_name[parsed.brand], display_name=parsed.model, match_key=key)
        item.brand, item.model, item.item_name = parsed.brand, parsed.model, parsed.display[:200]
        item.save(update_fields=["brand", "model", "item_name"])


